"Для фотосинтеза растению нужен углекислый газ.": "Фотосинтез үшін өсімдікке көмірқышқыл газы керек.",
"Как растения приспосабливаются": "Өсімдіктердің бейімделуі",
"Объяснять, как строение растения связано с условиями жизни": "Өсімдік құрылысының өмір сүру жағдайымен байланысын түсіндіру",
"Строение растения помогает ему жить там, где оно растёт: в пустыне — беречь воду, в воде — держаться на поверхности.": "Өсімдік құрылысы оған өсетін жерінде өмір сүруге көмектеседі: шөлде — суды үнемдеуге, суда — бетінде тұруға.",
"Верно. Строение растения помогает ему жить там, где оно растёт: в пустыне — беречь воду, в воде — держаться на поверхности.": "Дұрыс. Өсімдік құрылысы оған өсетін жерінде өмір сүруге көмектеседі: шөлде — суды үнемдеуге, суда — бетінде тұруға.",
"Неверно. Строение растения помогает ему жить там, где оно растёт: в пустыне — беречь воду, в воде — держаться на поверхности.": "Бұрыс. Өсімдік құрылысы оған өсетін жерінде өмір сүруге көмектеседі: шөлде — суды үнемдеуге, суда — бетінде тұруға.",
"Привет! Это Барсик. Сегодня наша тема — «как растения приспосабливаются». Нажимай на карточки и узнавай новое.": "Сәлем! Бұл Барсик. Бүгінгі тақырыбымыз — «өсімдіктердің бейімделуі». Карточкаларды бас та, жаңа нәрсені біл.",
"приспособление": "бейімделу",
"Приспособление — особенность строения или поведения, которая помогает живому организму выжить в его среде.": "Бейімделу — тірі ағзаға өз ортасында аман қалуға көмектесетін құрылыс немесе мінез-құлық ерекшелігі.",
"пустыня": "шөл",
"В пустыне мало воды. У саксаула и верблюжьей колючки длинные корни, мелкие листья или колючки: так меньше воды испаряется.": "Шөлде су аз. Сексеуіл мен жантақта тамырлары ұзын, жапырақтары ұсақ немесе тікенектері бар: сондықтан су аз буланады.",
"водоём": "су айдыны",
"У кувшинки широкие плавучие листья, а в стеблях камыша и рогоза есть воздушные полости. Поэтому они держатся на воде.": "Су лалагүлінің жапырақтары кең әрі суда жүзеді, қамыс пен қоғаның сабақтарында ауа қуыстары бар. Сондықтан олар су бетінде тұрады.",
"степь": "дала",
"У ковыля узкие свёрнутые листья: через них испаряется меньше влаги.": "Селеудің жапырақтары жіңішке, оралған: олар арқылы ылғал аз буланады.",
"север и зима": "солтүстік және қыс",
"У ели иглы вместо листьев, поэтому она зимой не теряет много воды, а снег с её наклонных ветвей легко скатывается.": "Шыршада жапырақ орнына ине жапырақтар болады, сондықтан қыста су аз жоғалтады, ал қар көлбеу бұтақтардан оңай сырғиды.",
"Деревья в лесу тянутся вверх, к свету. Растения на земле под деревьями растут в тени и часто цветут ранней весной.": "Орманда ағаштар жарыққа қарай жоғары созылады. Ағаштың астындағы өсімдіктер көлеңкеде өседі және жиі ерте көктемде гүлдейді.",
