"Камыш растёт в пустыне без воды.": "Қамыс судан тыс шөлде өседі.",
"Ковыль растёт в степи.": "Селеу далада өседі.",
"Мелкие листья помогают меньше испарять воду.": "Ұсақ жапырақтар суды аз буландыруға көмектеседі.",
"Все растения приспособлены к одинаковым условиям.": "Барлық өсімдіктер бірдей жағдайға бейімделген.",
"Воздушные полости помогают растению держаться на воде.": "Ауа қуыстары өсімдіктің су бетінде тұруына көмектеседі.",
"Красная книга и охрана природы": "Қызыл кітап және табиғатты қорғау",
"Знать, что такое Красная книга, и объяснять, как люди влияют на растения и животных": "Қызыл кітаптың не екенін білу, адамның өсімдіктер мен жануарларға әсерін түсіндіру",
"Красная книга — список редких и исчезающих растений и животных. Их охраняют, чтобы они не исчезли.": "Қызыл кітап — сирек және жойылып бара жатқан өсімдіктер мен жануарлардың тізімі. Олар жойылмауы үшін қорғалады.",
"Верно. Красная книга — список редких и исчезающих растений и животных. Их охраняют, чтобы они не исчезли.": "Дұрыс. Қызыл кітап — сирек және жойылып бара жатқан өсімдіктер мен жануарлардың тізімі. Олар жойылмауы үшін қорғалады.",
"Неверно. Красная книга — список редких и исчезающих растений и животных. Их охраняют, чтобы они не исчезли.": "Бұрыс. Қызыл кітап — сирек және жойылып бара жатқан өсімдіктер мен жануарлардың тізімі. Олар жойылмауы үшін қорғалады.",
"Привет! Это Барсик. Сегодня наша тема — «красная книга и охрана природы». Нажимай на карточки и узнавай новое.": "Сәлем! Бұл Барсик. Бүгінгі тақырыбымыз — «қызыл кітап және табиғатты қорғау». Карточкаларды бас та, жаңа нәрсені біл.",
"Красная книга — список редких и исчезающих растений и животных. Есть Красная книга Казахстана и международная Красная книга.": "Қызыл кітап — сирек және жойылып бара жатқан өсімдіктер мен жануарлардың тізімі. Қазақстанның Қызыл кітабы және халықаралық Қызыл кітап бар.",
"почему красная": "неге қызыл",
"Красный цвет — как сигнал тревоги: этим растениям и животным грозит исчезновение.": "Қызыл түс — дабыл белгісі: бұл өсімдіктер мен жануарлар жойылып кету қаупінде.",
"В Красную книгу Казахстана занесены, например, тюльпан Грейга и яблоня Сиверса.": "Қазақстанның Қызыл кітабына, мысалы, Грейг қызғалдағы мен Сиверс алмасы енгізілген.",
"В Красной книге Казахстана есть снежный барс, архар, кулан, джейран, розовый фламинго.": "Қазақстанның Қызыл кітабында ақ барыс, арқар, құлан, қарақұйрық, қызғылт фламинго бар.",
"причины": "себептер",
"Растения и животные исчезают из-за вырубки лесов, пожаров, загрязнения, браконьерства и сбора цветов.": "Өсімдіктер мен жануарлар ормандардың кесілуінен, өрттен, ластанудан, браконьерліктен және гүлдерді жұлудан жойылады.",
"охрана": "қорғау",
"Природу охраняют заповедники и национальные парки. Там нельзя рвать растения и охотиться. Самый старый заповедник Казахстана — Аксу-Жабаглы.": "Табиғатты қорық пен ұлттық парктер қорғайды. Онда өсімдіктерді жұлуға және аң аулауға болмайды. Қазақстанның ең көне қорығы — Ақсу-Жабағылы.",
