"Красная книга — это список редких и исчезающих видов.": "Қызыл кітап — сирек және жойылып бара жатқан түрлердің тізімі.",
"Растения из Красной книги можно рвать.": "Қызыл кітаптағы өсімдіктерді жұлуға болады.",
"Снежный барс занесён в Красную книгу Казахстана.": "Ақ барыс Қазақстанның Қызыл кітабына енген.",
"Заповедники охраняют природу.": "Қорықтар табиғатты қорғайды.",
"Браконьерство помогает природе.": "Браконьерлік табиғатқа көмектеседі.",
"Пожары могут навредить растениям и животным.": "Өрттер өсімдіктер мен жануарларға зиян келтіруі мүмкін.",
"Тюльпан Грейга — редкое растение.": "Грейг қызғалдағы — сирек өсімдік.",
"Красный цвет книги — цвет праздника.": "Кітаптың қызыл түсі — мереке түсі.",
"Человек может помочь редким животным.": "Адам сирек жануарларға көмектесе алады.",
"В национальных парках можно оставлять мусор.": "Ұлттық парктерде қоқыс тастауға болады.",
"Позвоночные и беспозвоночные животные": "Омыртқалы және омыртқасыз жануарлар",
"Классифицировать животных по строению тела": "Жануарларды дене құрылысына қарай жіктеу",
"У позвоночных есть позвоночник, у беспозвоночных его нет. У насекомых шесть ног, у пауков — восемь.": "Омыртқалыларда омыртқа бар, омыртқасыздарда жоқ. Жәндіктің алты аяғы, өрмекшінің сегіз аяғы бар.",
"Верно. У позвоночных есть позвоночник, у беспозвоночных его нет. У насекомых шесть ног, у пауков — восемь.": "Дұрыс. Омыртқалыларда омыртқа бар, омыртқасыздарда жоқ. Жәндіктің алты аяғы, өрмекшінің сегіз аяғы бар.",
"Неверно. У позвоночных есть позвоночник, у беспозвоночных его нет. У насекомых шесть ног, у пауков — восемь.": "Бұрыс. Омыртқалыларда омыртқа бар, омыртқасыздарда жоқ. Жәндіктің алты аяғы, өрмекшінің сегіз аяғы бар.",
"Привет! Это Барсик. Сегодня наша тема — «позвоночные и беспозвоночные животные». Нажимай на карточки и узнавай новое.": "Сәлем! Бұл Барсик. Бүгінгі тақырыбымыз — «омыртқалы және омыртқасыз жануарлар». Карточкаларды бас та, жаңа нәрсені біл.",
"У позвоночных животных есть позвоночник и внутренний скелет. К ним относят млекопитающих, птиц, рыб, земноводных и пресмыкающихся.": "Омыртқалы жануарларда омыртқа және ішкі қаңқа бар. Оларға сүтқоректілер, құстар, балықтар, қосмекенділер және бауырымен жорғалаушылар жатады.",
"У беспозвоночных нет позвоночника. К ним относят насекомых, пауков, червей, моллюсков и раков.": "Омыртқасыздарда омыртқа жоқ. Оларға жәндіктер, өрмекшілер, құрттар, ұлулар және шаяндар жатады.",
"классы": "кластар",
"Млекопитающие выкармливают детёнышей молоком. У птиц есть перья и крылья. У рыб — жабры и чешуя. Лягушки — земноводные. Ящерицы и змеи — пресмыкающиеся.": "Сүтқоректілер төлдерін сүтпен қоректендіреді. Құстарда қауырсын мен қанат бар. Балықтарда желбезек пен қабыршақ бар. Бақалар — қосмекенділер. Кесірткелер мен жыландар — бауырымен жорғалаушылар.",
"насекомые": "жәндіктер",
"У насекомых шесть ног и тело из трёх частей: голова, грудь, брюшко. Это бабочки, муравьи, жуки, пчёлы.": "Жәндіктің алты аяғы бар, денесі үш бөліктен тұрады: бас, көкірек, құрсақ. Бұл көбелектер, құмырсқалар, қоңыздар, аралар.",
"пауки": "өрмекшілер",
"У пауков восемь ног. Паук не насекомое, он относится к паукообразным.": "Өрмекшінің сегіз аяғы бар. Өрмекші жәндік емес, ол өрмекшітәрізділерге жатады.",
"важно": "маңызды",
"Дождевой червь и улитка тоже беспозвоночные. Они важны для природы: дождевые черви рыхлят почву.": "Жауын құрты мен ұлу да омыртқасыздар. Олар табиғат үшін маңызды: жауын құрттары топырақты борпылдатады.",
"Какое это животное?": "Бұл қандай жануар?",
