"Привет! Это Барсик. Сегодня наша тема — «среда обитания и отношения животных». Нажимай на карточки и узнавай новое.": "Сәлем! Бұл Барсик. Бүгінгі тақырыбымыз — «мекен ету ортасы және жануарлардың қарым-қатынасы». Карточкаларды бас та, жаңа нәрсені біл.",
"Среда обитания — это место, где живёт организм и где у него есть всё необходимое: пища, вода, воздух, укрытие.": "Мекен ету ортасы — ағза өмір сүретін және оған қажетті бәрі бар орын: қорек, су, ауа, паналайтын жер.",
"виды сред": "орта түрлері",
