"разрушители": "ыдыратушылар",
"Грибы и бактерии разлагают остатки растений и животных, и в почве появляются вещества для новых растений.": "Саңырауқұлақтар мен бактериялар өсімдіктер мен жануарлардың қалдықтарын ыдыратады, топырақта жаңа өсімдіктерге арналған заттар пайда болады.",
"Численность — это число животных. Она зависит от пищи, воды, погоды, врагов и человека.": "Сан — жануарлардың саны. Ол қорекке, суға, ауа райына, жауларға және адамға байланысты.",
"что меняет": "не өзгертеді",
"Если вырубить лес или осушить водоём, животные теряют дом. Если исчезают хищники, травоядных становится слишком много.": "Орманды кессе немесе су айдынын құртса, жануарлар үйінен айырылады. Жыртқыштар жойылса, шөпқоректілер тым көбейіп кетеді.",
