"Почему важно беречь каждое звено цепи?": "Тізбектің әр буынын неге қорғау керек?",
"все звенья связаны": "барлық буындар өзара байланысты",
"звенья не важны": "буындар маңызды емес",
"нужны только хищники": "тек жыртқыштар керек",
"нужны только растения": "тек өсімдіктер керек",
"Какое звено в цепи «трава → заяц → волк» травоядное?": "«Шөп → қоян → қасқыр» тізбегінде шөпқоректі кім?",
"Хищник — первое звено цепи питания.": "Жыртқыш — қорек тізбегінің бірінші буыны.",
"Насекомые опыляют цветы.": "Жәндіктер гүлдерді тозаңдандырады.",
"Вырубка леса не влияет на животных.": "Орман кесу жануарларға әсер етпейді.",
"Грибы и бактерии разлагают остатки растений и животных.": "Саңырауқұлақтар мен бактериялар өсімдіктер мен жануарлардың қалдықтарын ыдыратады.",
"Численность — это число животных.": "Сан — жануарлардың саны.",
"В цепи «трава → заяц → лиса» лиса питается травой.": "«Шөп → қоян → түлкі» тізбегінде түлкі шөппен қоректенеді.",
"Охрана природы помогает сохранить животных.": "Табиғатты қорғау жануарларды сақтауға көмектеседі.",
"Если исчезнет трава, пострадают и травоядные.": "Шөп жойылса, шөпқоректілер де зардап шегеді.",
"Птицы могут разносить семена.": "Құстар тұқымдарды таратуы мүмкін.",
"Описывать путь пищи по органам пищеварения": "Тағамның ас қорыту мүшелері арқылы жүретін жолын сипаттау",
"Пища проходит путь: рот → пищевод → желудок → тонкая кишка → толстая кишка. Питательные вещества всасываются в кровь.": "Тағам жолы: ауыз → өңеш → асқазан → жіңішке ішек → тоқ ішек. Қоректік заттар қанға сіңеді.",
"Верно. Пища проходит путь: рот → пищевод → желудок → тонкая кишка → толстая кишка. Питательные вещества всасываются в кровь.": "Дұрыс. Тағам жолы: ауыз → өңеш → асқазан → жіңішке ішек → тоқ ішек. Қоректік заттар қанға сіңеді.",
"Неверно. Пища проходит путь: рот → пищевод → желудок → тонкая кишка → толстая кишка. Питательные вещества всасываются в кровь.": "Бұрыс. Тағам жолы: ауыз → өңеш → асқазан → жіңішке ішек → тоқ ішек. Қоректік заттар қанға сіңеді.",
"Привет! Это Барсик. Сегодня наша тема — «пищеварение». Нажимай на карточки и узнавай новое.": "Сәлем! Бұл Барсик. Бүгінгі тақырыбымыз — «ас қорыту». Карточкаларды бас та, жаңа нәрсені біл.",
"зачем нужна пища": "тағам не үшін керек",
"Пища даёт организму энергию и вещества для роста. Она должна быть переработана — это называется пищеварением.": "Тағам ағзаға қуат және өсу үшін заттар береді. Ол өңделуі керек — мұны ас қорыту дейді.",
"Во рту зубы измельчают пищу, а слюна размягчает её. Здесь пищеварение начинается.": "Ауызда тістер тағамды ұсақтайды, ал сілекей оны жұмсартады. Ас қорыту осы жерден басталады.",
"путь пищи": "тағам жолы",
"Рот → пищевод → желудок → тонкая кишка → толстая кишка. Вместе это пищеварительная система.": "Ауыз → өңеш → асқазан → жіңішке ішек → тоқ ішек. Бәрі бірге ас қорыту жүйесін құрайды.",
"В желудке пища перемешивается и перерабатывается желудочным соком.": "Асқазанда тағам араласады және асқазан сөлімен өңделеді.",
"В тонкой кишке питательные вещества всасываются в кровь. В толстой кишке остаётся то, что организму не нужно.": "Жіңішке ішекте қоректік заттар қанға сіңеді. Тоқ ішекте ағзаға қажет емес нәрсе қалады.",
"правила": "ережелер",
"Пищу надо тщательно жевать. Нужно мыть руки перед едой, есть вовремя и разнообразно, не переедать.": "Тағамды жақсылап шайнау керек. Тамақтан бұрын қолды жуу, уақытында және әртүрлі тамақтану, шектен тыс жемеу қажет.",
