"Описывать путь воздуха и работу сердца и крови": "Ауа жолын, жүрек пен қанның жұмысын сипаттау",
"Воздух идёт по носу, трахее и бронхам в лёгкие. Сердце гонит кровь по сосудам и разносит кислород по телу.": "Ауа мұрын, кеңірдек және бронхтар арқылы өкпеге барады. Жүрек қанды тамырлармен айдап, оттекті бүкіл денеге таратады.",
