"Кровь разносит по телу кислород и питательные вещества и уносит ненужное. Красный цвет ей дают красные клетки крови.": "Қан денеге оттек пен қоректік заттарды таратады және қажетсіздерін әкетеді. Оған қызыл түсті қанның қызыл жасушалары береді.",
