"Что даёт крови красный цвет?": "Қанға қызыл түс беретін не?",
"красные клетки крови": "қанның қызыл жасушалары",
"Воздух проходит через нос, трахею и бронхи в лёгкие.": "Ауа мұрын, кеңірдек және бронхтар арқылы өкпеге барады.",
"При выдохе в лёгкие поступает кислород.": "Дем шығарғанда өкпеге оттек түседі.",
"Сердце — мышечный орган.": "Жүрек — бұлшықетті мүше.",
"Кровь течёт только по лёгким.": "Қан тек өкпе арқылы ағады.",
"Пульс можно почувствовать на запястье.": "Тамыр соғысын білекте сезуге болады.",
"При беге сердце бьётся быстрее.": "Жүгіргенде жүрек жиі соғады.",
"Капилляры — самые широкие сосуды.": "Капиллярлар — ең жуан тамырлар.",
"Кровь разносит по телу кислород.": "Қан денеге оттек таратады.",
"Дышать лучше ртом, чем носом.": "Мұрынмен гөрі ауызбен тыныс алған жақсы.",
"Сердце, кровь и сосуды образуют кровеносную систему.": "Жүрек, қан және тамырлар қан айналу жүйесін құрайды.",
"Здоровье и защита от болезней": "Денсаулық және аурудан қорғану",
"Знать, как беречь здоровье и защищаться от инфекций": "Денсаулықты сақтауды және жұқпалы аурулардан қорғануды білу",
"Здоровью помогают режим дня, сон, движение, чистота и прививки. Многие инфекции передаются через грязные руки, воздух и воду.": "Денсаулыққа күн тәртібі, ұйқы, қозғалыс, тазалық және екпелер көмектеседі. Көптеген жұқпалар лас қол, ауа және су арқылы жұғады.",
"Верно. Здоровью помогают режим дня, сон, движение, чистота и прививки. Многие инфекции передаются через грязные руки, воздух и воду.": "Дұрыс. Денсаулыққа күн тәртібі, ұйқы, қозғалыс, тазалық және екпелер көмектеседі. Көптеген жұқпалар лас қол, ауа және су арқылы жұғады.",
"Неверно. Здоровью помогают режим дня, сон, движение, чистота и прививки. Многие инфекции передаются через грязные руки, воздух и воду.": "Бұрыс. Денсаулыққа күн тәртібі, ұйқы, қозғалыс, тазалық және екпелер көмектеседі. Көптеген жұқпалар лас қол, ауа және су арқылы жұғады.",
"Привет! Это Барсик. Сегодня наша тема — «здоровье и защита от болезней». Нажимай на карточки и узнавай новое.": "Сәлем! Бұл Барсик. Бүгінгі тақырыбымыз — «денсаулық және аурудан қорғану». Карточкаларды бас та, жаңа нәрсені біл.",
"здоровье": "денсаулық",
"Здоровье зависит от режима дня, питания, сна, движения и чистоты.": "Денсаулық күн тәртібіне, тамақтануға, ұйқыға, қозғалысқа және тазалыққа байланысты.",
"режим дня": "күн тәртібі",
"Режим дня — порядок труда, отдыха, питания и сна. Школьнику нужно спать не менее 9 часов.": "Күн тәртібі — еңбек, демалыс, тамақтану және ұйқы реті. Оқушыға кемінде 9 сағат ұйықтау керек.",
"микробы": "микробтар",
"Болезни вызывают микробы: бактерии и вирусы. Они передаются через воздух, грязные руки, воду и продукты.": "Ауруларды микробтар — бактериялар мен вирустар тудырады. Олар ауа, лас қол, су және тағам арқылы жұғады.",
"иммунитет": "иммунитет",
"Иммунитет — защита организма от болезней. Его укрепляют закаливание, движение, овощи и фрукты.": "Иммунитет — ағзаның аурулардан қорғанысы. Оны шынықтыру, қозғалыс, көкөніс пен жемістер нығайтады.",
"прививки": "екпелер",
"Прививки учат организм бороться с опасными болезнями заранее. Делают их врачи.": "Екпелер ағзаны қауіпті ауруларға қарсы алдын ала күресуге үйретеді. Оларды дәрігерлер салады.",
"если заболел": "ауырып қалсаң",
"При болезни надо сказать взрослым и обратиться к врачу. Нельзя лечиться самому и принимать лекарства без разрешения взрослых.": "Ауырсаң, үлкендерге айту және дәрігерге бару керек. Өз бетіңше емделуге және үлкендердің рұқсатынсыз дәрі ішуге болмайды.",
"Полезно или вредно для здоровья?": "Денсаулыққа пайдалы ма, зиянды ма?",
"утренняя зарядка": "таңертеңгі жаттығу",
