"Школьнику достаточно спать 4 часа.": "Оқушыға 4 сағат ұйқы жеткілікті.",
"Лекарства можно принимать без разрешения взрослых.": "Дәрілерді үлкендердің рұқсатынсыз ішуге болады.",
"Норма температуры тела — около 36,6 °C.": "Дене температурасының нормасы — шамамен 36,6 °C.",
"Закаливание укрепляет иммунитет.": "Шынығу иммунитетті нығайтады.",
"Фрукты и овощи полезны для здоровья.": "Жеміс пен көкөніс денсаулыққа пайдалы.",
"Свойства веществ": "Заттардың қасиеттері",
"Описывать вещества по их свойствам": "Заттарды қасиеттері бойынша сипаттау",
"Вещества бывают твёрдыми, жидкими и газообразными. У них разные свойства: растворимость, прозрачность, теплопроводность, электропроводность.": "Заттар қатты, сұйық және газ күйінде болады. Олардың қасиеттері әртүрлі: ерігіштік, мөлдірлік, жылу өткізгіштік, электр өткізгіштік.",
"Верно. Вещества бывают твёрдыми, жидкими и газообразными. У них разные свойства: растворимость, прозрачность, теплопроводность, электропроводность.": "Дұрыс. Заттар қатты, сұйық және газ күйінде болады. Олардың қасиеттері әртүрлі: ерігіштік, мөлдірлік, жылу өткізгіштік, электр өткізгіштік.",
"Неверно. Вещества бывают твёрдыми, жидкими и газообразными. У них разные свойства: растворимость, прозрачность, теплопроводность, электропроводность.": "Бұрыс. Заттар қатты, сұйық және газ күйінде болады. Олардың қасиеттері әртүрлі: ерігіштік, мөлдірлік, жылу өткізгіштік, электр өткізгіштік.",
"Привет! Это Барсик. Сегодня наша тема — «свойства веществ». Нажимай на карточки и узнавай новое.": "Сәлем! Бұл Барсик. Бүгінгі тақырыбымыз — «заттардың қасиеттері». Карточкаларды бас та, жаңа нәрсені біл.",
"что такое вещество": "зат дегеніміз не",
"Вещество — то, из чего состоят предметы. Например, ложка сделана из металла, стакан — из стекла.": "Зат — заттар қандай материалдан тұрады. Мысалы, қасық металдан, стақан шыныдан жасалған.",
"состояния": "күйлері",
"Вещества бывают твёрдыми, жидкими и газообразными. Твёрдое сохраняет форму, жидкость принимает форму сосуда, газ заполняет всё место.": "Заттар қатты, сұйық және газ күйінде болады. Қатты зат пішінін сақтайды, сұйықтық ыдыстың пішінін қабылдайды, газ барлық орынды толтырады.",
"растворимость": "ерігіштік",
"Одни вещества растворяются в воде — соль, сахар. Другие не растворяются — песок, мел, растительное масло.": "Кейбір заттар суда ериді — тұз, қант. Басқалары ерімейді — құм, бор, өсімдік майы.",
"прозрачность": "мөлдірлік",
"Стекло и вода прозрачные, бумага и дерево непрозрачные.": "Шыны мен су мөлдір, қағаз бен ағаш мөлдір емес.",
"проводят тепло": "жылуды өткізеді",
"Металлы хорошо проводят тепло: железная ложка в горячем чае быстро нагревается. Дерево и пластик проводят тепло плохо.": "Металдар жылуды жақсы өткізеді: ыстық шайдағы темір қасық тез қызады. Ағаш пен пластик жылуды нашар өткізеді.",
"проводят ток": "токты өткізеді",
"Металлы проводят электрический ток. Резина, пластик и стекло ток не проводят — их называют изоляторами.": "Металдар электр тогын өткізеді. Резина, пластик және шыны токты өткізбейді — оларды оқшаулағыштар деп атайды.",
