"Что сохраняет форму?": "Не пішінін сақтайды?",
"Что заполняет всё место, в котором находится?": "Не өзі тұрған орынның бәрін толтырады?",
"Почему ручки кастрюль делают из пластика или дерева?": "Кастрюльдің тұтқасын неге пластиктен немесе ағаштан жасайды?",
"они плохо проводят тепло": "олар жылуды нашар өткізеді",
"они красивее": "олар әдемірек",
"они тяжелее": "олар ауыр",
"они прозрачные": "олар мөлдір",
"Соль растворяется в воде.": "Тұз суда ериді.",
"Песок растворяется в воде.": "Құм суда ериді.",
"Жидкость сохраняет форму.": "Сұйықтық пішінін сақтайды.",
"Воздух — газообразное вещество.": "Ауа — газ тәрізді зат.",
"Металлы хорошо проводят тепло.": "Металдар жылуды жақсы өткізеді.",
"Резина проводит электрический ток.": "Резина электр тогын өткізеді.",
"Стекло прозрачное.": "Шыны мөлдір.",
"Дерево хорошо проводит тепло.": "Ағаш жылуды жақсы өткізеді.",
"Газ заполняет всё место, где находится.": "Газ өзі тұрған орынның бәрін толтырады.",
"Очистка и бережное использование воды": "Суды тазарту және үнемдеу",
"Знать способы очистки воды и правила её экономии": "Суды тазарту тәсілдерін және үнемдеу ережелерін білу",
"Воду очищают отстаиванием, фильтрованием и кипячением. Воду надо беречь: пресной воды на Земле мало.": "Суды тұндыру, сүзу және қайнату арқылы тазартады. Суды үнемдеу керек: жер бетінде тұщы су аз.",
"Верно. Воду очищают отстаиванием, фильтрованием и кипячением. Воду надо беречь: пресной воды на Земле мало.": "Дұрыс. Суды тұндыру, сүзу және қайнату арқылы тазартады. Суды үнемдеу керек: жер бетінде тұщы су аз.",
"Неверно. Воду очищают отстаиванием, фильтрованием и кипячением. Воду надо беречь: пресной воды на Земле мало.": "Бұрыс. Суды тұндыру, сүзу және қайнату арқылы тазартады. Суды үнемдеу керек: жер бетінде тұщы су аз.",
"Привет! Это Барсик. Сегодня наша тема — «очистка и бережное использование воды». Нажимай на карточки и узнавай новое.": "Сәлем! Бұл Барсик. Бүгінгі тақырыбымыз — «суды тазарту және үнемдеу». Карточкаларды бас та, жаңа нәрсені біл.",
"пресная вода": "тұщы су",
"Пресная вода нужна для питья, готовки, земледелия. Её на Земле гораздо меньше, чем солёной.": "Тұщы су ішуге, тамақ әзірлеуге, егін шаруашылығына керек. Жер бетінде ол тұзды судан әлдеқайда аз.",
"загрязнение": "ластану",
"Воду загрязняют отходы заводов, мусор, удобрения, нефть. Из загрязнённой воды можно заболеть.": "Суды зауыт қалдықтары, қоқыс, тыңайтқыштар, мұнай ластайды. Ластанған судан ауырып қалуға болады.",
"отстаивание и фильтр": "тұндыру және сүзгі",
"Грязную воду можно отстоять, чтобы осел песок, а затем пропустить через фильтр: слои ваты, песка и угля.": "Лас суды тұндыруға болады, сонда құм түбіне шөгеді, содан кейін сүзгіден өткізеді: мақта, құм және көмір қабаттары.",
"Кипячение убивает микробов. Сырую воду из реки или колодца надо кипятить.": "Қайнату микробтарды өлтіреді. Өзен немесе құдықтан алынған шикі суды қайнату керек.",
"станции": "станциялар",
"В городах воду очищают на водоочистных станциях и по трубам подают в дома.": "Қалаларда суды су тазалау станцияларында тазартады және құбырлар арқылы үйлерге береді.",
"Закрывай кран, пока чистишь зубы, чини протекающие краны, не мусори у водоёмов. Пример беды — Аральское море, которое сильно обмелело.": "Тіс тазалағанда шүмекті жап, ақаулы шүмектерді жөнде, су айдындарының жағасына қоқыс тастама. Арал теңізі қатты саяздады — бұл ауыр сабақ.",
