"Мусор в водоём не вредит воде.": "Су айдынындағы қоқыс суға зиян келтірмейді.",
"Фильтр можно сделать из ваты, песка и угля.": "Сүзгіні мақта, құм және көмірден жасауға болады.",
"Кипячение убивает микробов.": "Қайнату микробтарды өлтіреді.",
"Почвы: состав и виды": "Топырақ: құрамы және түрлері",
"Описывать состав почвы и виды почв Казахстана": "Топырақ құрамын және Қазақстан топырақтарының түрлерін сипаттау",
"Плодородие почвы зависит от перегноя. Самые плодородные почвы — чернозёмы.": "Топырақтың құнарлылығы қарашіріндіге байланысты. Ең құнарлы топырақ — қара топырақ.",
"Верно. Плодородие почвы зависит от перегноя. Самые плодородные почвы — чернозёмы.": "Дұрыс. Топырақтың құнарлылығы қарашіріндіге байланысты. Ең құнарлы топырақ — қара топырақ.",
"Неверно. Плодородие почвы зависит от перегноя. Самые плодородные почвы — чернозёмы.": "Бұрыс. Топырақтың құнарлылығы қарашіріндіге байланысты. Ең құнарлы топырақ — қара топырақ.",
"Привет! Это Барсик. Сегодня наша тема — «почвы: состав и виды». Нажимай на карточки и узнавай новое.": "Сәлем! Бұл Барсик. Бүгінгі тақырыбымыз — «топырақ: құрамы және түрлері». Карточкаларды бас та, жаңа нәрсені біл.",
"состав почвы": "топырақ құрамы",
"Почва состоит из песка, глины, перегноя, воды, воздуха и минеральных солей.": "Топырақ құм, саз, қарашірінді, су, ауа және минерал тұздардан тұрады.",
"Перегной образуется из остатков растений и животных. Он делает почву тёмной и плодородной.": "Қарашірінді өсімдіктер мен жануарлардың қалдықтарынан түзіледі. Ол топырақты қара және құнарлы етеді.",
"Плодородие — способность почвы давать растениям всё необходимое для жизни.": "Құнарлылық — топырақтың өсімдіктерге өмір сүруге қажетті бәрін беру қабілеті.",
"песок и глина": "құм және саз",
"Песчаная почва хорошо пропускает воду, но плохо её держит. Глинистая почва держит воду, но плохо пропускает воздух.": "Құмды топырақ суды жақсы өткізеді, бірақ нашар ұстайды. Сазды топырақ суды ұстайды, бірақ ауаны нашар өткізеді.",
"виды почв": "топырақ түрлері",
"В Казахстане есть чернозёмы, каштановые почвы, бурые и серо-бурые почвы пустынь, сероземы на юге.": "Қазақстанда қара топырақ, қара қоңыр топырақ, шөл зонасының қоңыр және сұр-қоңыр топырақтары, оңтүстікте сұр топырақ бар.",
"Почву разрушают ветер и вода, а также вырубка лесов и неправильная вспашка. Почву защищают лесополосы и севооборот.": "Топырақты жел мен су бұзады, сондай-ақ орманды кесу және дұрыс жыртпау бұзады. Топырақты орман белдеулері мен ауыспалы егіс қорғайды.",
