"Дождевые черви рыхлят почву.": "Жауын құрттары топырақты борпылдатады.",
"Чернозём — одна из самых плодородных почв.": "Қара топырақ — ең құнарлы топырақтардың бірі.",
"Глинистая почва хорошо пропускает воду.": "Сазды топырақ суды жақсы өткізеді.",
"Лесополосы защищают почву от ветра.": "Орман белдеулері топырақты желден қорғайды.",
"Почва состоит только из песка.": "Топырақ тек құмнан тұрады.",
"В Казахстане есть чернозёмы.": "Қазақстанда қара топырақ бар.",
"Вырубка леса помогает почве.": "Орманды кесу топыраққа көмектеседі.",
"В почве есть вода и воздух.": "Топырақта су мен ауа бар.",
"Строение Земли и её вращение": "Жердің құрылысы және айналуы",
"Описывать строение Земли и следствия вращения": "Жердің құрылысын және айналудың салдарын сипаттау",
"Земля вращается вокруг своей оси за сутки и обходит Солнце за год. Поэтому сменяются день и ночь, времена года.": "Жер өз осінен тәулікте айналады және жылда Күнді айналып шығады. Сондықтан күн мен түн, жыл мезгілдері ауысады.",
"Верно. Земля вращается вокруг своей оси за сутки и обходит Солнце за год. Поэтому сменяются день и ночь, времена года.": "Дұрыс. Жер өз осінен тәулікте айналады және жылда Күнді айналып шығады. Сондықтан күн мен түн, жыл мезгілдері ауысады.",
"Неверно. Земля вращается вокруг своей оси за сутки и обходит Солнце за год. Поэтому сменяются день и ночь, времена года.": "Бұрыс. Жер өз осінен тәулікте айналады және жылда Күнді айналып шығады. Сондықтан күн мен түн, жыл мезгілдері ауысады.",
"Привет! Это Барсик. Сегодня наша тема — «строение земли и её вращение». Нажимай на карточки и узнавай новое.": "Сәлем! Бұл Барсик. Бүгінгі тақырыбымыз — «жердің құрылысы және айналуы». Карточкаларды бас та, жаңа нәрсені біл.",
"форма": "пішіні",
"Земля имеет форму шара. Модель Земли — глобус. На нём есть полюса и экватор.": "Жердің пішіні — шар. Жердің моделі — глобус. Онда полюстер мен экватор бар.",
"строение": "құрылысы",
"Внутри Земли три слоя: земная кора, мантия и ядро. Мы живём на земной коре — тонком твёрдом слое.": "Жердің ішінде үш қабат бар: жер қыртысы, мантия және ядро. Біз жер қыртысында — жұқа қатты қабатта тұрамыз.",
"ось": "ось",
"Земля вращается вокруг своей оси. Один оборот занимает сутки. Поэтому сменяются день и ночь.": "Жер өз осінен айналады. Бір айналым бір тәулікке созылады. Сондықтан күн мен түн ауысады.",
"день и ночь": "күн мен түн",
"Солнце освещает только половину Земли. Там день, а на другой половине — ночь.": "Күн Жердің тек жартысын жарықтандырады. Онда күндіз, ал екінші жартысында түн.",
"год": "жыл",
"За год Земля делает полный оборот вокруг Солнца. Ось Земли наклонена, поэтому сменяются времена года.": "Жер бір жылда Күнді толық айналып шығады. Жердің осі көлбеу, сондықтан жыл мезгілдері ауысады.",
"луна": "ай",
"Луна — спутник Земли. Она обращается вокруг Земли примерно за месяц и светит отражённым светом Солнца.": "Ай — Жердің серігі. Ол Жерді шамамен бір айда айналады және Күннің шағылысқан жарығымен жарқырайды.",
