"Знать главные события освоения космоса и планеты Солнечной системы": "Ғарышты игерудегі басты оқиғаларды және Күн жүйесінің планеталарын білу",
"Солнце — звезда в центре Солнечной системы. В 1957 году запущен первый спутник, в 1961 году Юрий Гагарин полетел в космос. Космодром Байконур находится в Казахстане.": "Күн — Күн жүйесінің ортасындағы жұлдыз. 1957 жылы алғашқы серік ұшырылды, 1961 жылы Юрий Гагарин ғарышқа ұшты. Байқоңыр ғарыш айлағы Қазақстанда орналасқан.",
"Верно. Солнце — звезда в центре Солнечной системы. В 1957 году запущен первый спутник, в 1961 году Юрий Гагарин полетел в космос. Космодром Байконур находится в Казахстане.": "Дұрыс. Күн — Күн жүйесінің ортасындағы жұлдыз. 1957 жылы алғашқы серік ұшырылды, 1961 жылы Юрий Гагарин ғарышқа ұшты. Байқоңыр ғарыш айлағы Қазақстанда орналасқан.",
"Неверно. Солнце — звезда в центре Солнечной системы. В 1957 году запущен первый спутник, в 1961 году Юрий Гагарин полетел в космос. Космодром Байконур находится в Казахстане.": "Бұрыс. Күн — Күн жүйесінің ортасындағы жұлдыз. 1957 жылы алғашқы серік ұшырылды, 1961 жылы Юрий Гагарин ғарышқа ұшты. Байқоңыр ғарыш айлағы Қазақстанда орналасқан.",
"Привет! Это Барсик. Сегодня наша тема — «освоение космоса». Нажимай на карточки и узнавай новое.": "Сәлем! Бұл Барсик. Бүгінгі тақырыбымыз — «ғарышты игеру». Карточкаларды бас та, жаңа нәрсені біл.",
"Солнечная система": "Күн жүйесі",
"В центре Солнечной системы — звезда Солнце. Вокруг него обращаются восемь планет: Меркурий, Венера, Земля, Марс, Юпитер, Сатурн, Уран, Нептун.": "Күн жүйесінің ортасында Күн жұлдызы бар. Оның айналасында сегіз планета: Меркурий, Шолпан, Жер, Марс, Юпитер, Сатурн, Уран, Нептун айналады.",
"первый спутник": "алғашқы серік",
"4 октября 1957 года был запущен первый искусственный спутник Земли. Запуск был с космодрома Байконур.": "1957 жылғы 4 қазанда Жердің алғашқы жасанды серігі ұшырылды. Ол Байқоңыр ғарыш айлағынан ұшырылды.",
"Гагарин": "Гагарин",
"12 апреля 1961 года Юрий Гагарин на корабле «Восток-1» стал первым человеком в космосе. Старт был с Байконура. День космонавтики отмечают 12 апреля.": "1961 жылғы 12 сәуірде Юрий Гагарин «Восток-1» кемесімен ғарышқа ұшқан алғашқы адам болды. Ұшу Байқоңырдан жүргізілді. Ғарышкерлер күні 12 сәуірде аталады.",
"первые в космосе": "ғарыштағы алғашқылар",
"Валентина Терешкова — первая женщина в космосе (1963). Алексей Леонов — первый вышел в открытый космос (1965). Нил Армстронг — первый человек на Луне (1969).": "Валентина Терешкова — ғарышқа ұшқан алғашқы әйел (1963). Алексей Леонов — ашық ғарышқа шыққан алғашқы адам (1965). Нил Армстронг — Айға түскен алғашқы адам (1969).",
"космонавты Казахстана": "Қазақстан ғарышкерлері",
"Токтар Аубакиров, Талгат Мусабаев и Айдын Аймбетов — космонавты из Казахстана.": "Тоқтар Әубәкіров, Талғат Мұсабаев және Айдын Аймбетов — Қазақстаннан шыққан ғарышкерлер.",
"станция и телескопы": "станция және телескоптар",
"На Международной космической станции работают космонавты разных стран. Телескопы помогают изучать звёзды и планеты.": "Халықаралық ғарыш станциясында әртүрлі елдердің ғарышкерлері жұмыс істейді. Телескоптар жұлдыздар мен планеталарды зерттеуге көмектеседі.",
