"Айдын Аймбетов — космонавт Казахстана.": "Айдын Аймбетов — Қазақстанның ғарышкері.",
"Силы: упругости, тяжести, трения": "Күштер: серпімділік, ауырлық, үйкеліс",
"Различать силы и определять направление их действия": "Күштерді ажырату және олардың әсер бағытын анықтау",
"Сила упругости возвращает форму тела, сила тяжести тянет вниз, сила трения направлена против движения. Силу измеряют динамометром в ньютонах.": "Серпімділік күші дененің пішінін қайтарады, ауырлық күші төмен тартады, үйкеліс күші қозғалысқа қарсы бағытталған. Күшті динамометрмен ньютонмен өлшейді.",
"Верно. Сила упругости возвращает форму тела, сила тяжести тянет вниз, сила трения направлена против движения. Силу измеряют динамометром в ньютонах.": "Дұрыс. Серпімділік күші дененің пішінін қайтарады, ауырлық күші төмен тартады, үйкеліс күші қозғалысқа қарсы бағытталған. Күшті динамометрмен ньютонмен өлшейді.",
"Неверно. Сила упругости возвращает форму тела, сила тяжести тянет вниз, сила трения направлена против движения. Силу измеряют динамометром в ньютонах.": "Бұрыс. Серпімділік күші дененің пішінін қайтарады, ауырлық күші төмен тартады, үйкеліс күші қозғалысқа қарсы бағытталған. Күшті динамометрмен ньютонмен өлшейді.",
"Привет! Это Барсик. Сегодня наша тема — «силы: упругости, тяжести, трения». Нажимай на карточки и узнавай новое.": "Сәлем! Бұл Барсик. Бүгінгі тақырыбымыз — «күштер: серпімділік, ауырлық, үйкеліс». Карточкаларды бас та, жаңа нәрсені біл.",
"сила": "күш",
"Силой называют действие одного тела на другое. Сила может изменить движение или форму тела.": "Күш деп бір дененің екіншісіне әсерін атайды. Күш қозғалысты немесе дененің пішінін өзгерте алады.",
"упругость": "серпімділік",
"Сила упругости возникает при растяжении, сжатии, изгибе. Она возвращает тело к прежней форме (пружина, резинка, мяч).": "Серпімділік күші созғанда, қысқанда, июге ғана пайда болады. Ол денені бұрынғы пішініне қайтарады (серіппе, резеңке, доп).",
"тяжесть": "ауырлық",
"Сила тяжести притягивает все тела к Земле. Она направлена вниз. Из-за неё предметы падают.": "Ауырлық күші барлық денелерді Жерге тартады. Ол төмен бағытталған. Соның әсерінен заттар құлайды.",
"трение": "үйкеліс",
"Сила трения возникает при движении одного тела по поверхности другого и направлена против движения.": "Үйкеліс күші бір дене екіншісінің бетімен қозғалғанда пайда болады және қозғалысқа қарсы бағытталған.",
"польза и вред трения": "үйкелістің пайдасы мен зияны",
"Трение полезно: оно не даёт предметам скользить, шинам — проскальзывать. Но оно изнашивает детали. Для уменьшения трения применяют смазку.": "Үйкеліс пайдалы: ол заттардың сырғымауына, дөңгелектердің тайғанамауына көмектеседі. Бірақ ол бөлшектерді тоздырады. Үйкелісті азайту үшін майлайды.",
"измерение": "өлшеу",
"Силу измеряют прибором динамометром. Единица силы — ньютон (Н).": "Күшті динамометр құралымен өлшейді. Күштің бірлігі — ньютон (Н).",
"Какая сила действует?": "Қандай күш әсер етеді?",
