"санки тяжело тянуть по асфальту": "шананы асфальтпен тарту қиын",
"ось колеса скрипит без смазки": "майсыз доңғалақ осі сықырлайды",
"Какая сила притягивает тела к Земле?": "Денелерді Жерге қай күш тартады?",
