"чёрная ткань": "қара мата",
"земля": "жер",
"Какие предметы больше поглощают свет?": "Қандай заттар жарықты көбірек сіңіреді?",
"тёмные": "қою түсті",
"светлые": "ашық түсті",
"прозрачные": "мөлдір",
"гладкие зеркала": "тегіс айналар",
"Зачем нужны светоотражающие значки?": "Жарық шағылыстыратын белгілер не үшін керек?",
"чтобы пешехода было видно в темноте": "жаяу жүргіншіні қараңғыда көру үшін",
