"собственный свет": "өз жарығын",
"Какой материал полупрозрачный?": "Қай материал жартылай мөлдір?",
"Солнце — источник света.": "Күн — жарық көзі.",
"Тень появляется за непрозрачным предметом.": "Көлеңке мөлдір емес заттың артында пайда болады.",
"Чем ближе предмет к лампе, тем больше его тень.": "Зат шамға жақын болған сайын, оның көлеңкесі үлкен болады.",
"Стекло не пропускает свет.": "Шыны жарықты өткізбейді.",
"Зеркало хорошо отражает свет.": "Айна жарықты жақсы шағылыстырады.",
"Тёмные предметы отражают свет лучше светлых.": "Қою түсті заттар жарықты ашық түстіден жақсы шағылыстырады.",
"Светоотражающие значки помогают водителям видеть пешеходов.": "Жарық шағылыстыратын белгілер жүргізушілерге жаяу жүргіншілерді көруге көмектеседі.",
"Картон — прозрачный предмет.": "Картон — мөлдір зат.",
"Вода пропускает свет.": "Су жарықты өткізеді.",
"Звук и его громкость": "Дыбыс және оның қаттылығы",
"Объяснять, как возникает звук и от чего зависит громкость": "Дыбыстың қалай пайда болатынын және қаттылығы неге байланысты екенін түсіндіру",
"Звук возникает от колебаний. Чем дальше источник, тем звук тише. Громкий шум вреден для слуха.": "Дыбыс тербелістен пайда болады. Көзден алыстаған сайын дыбыс бәсең. Қатты шу есту қабілетіне зиян.",
"Верно. Звук возникает от колебаний. Чем дальше источник, тем звук тише. Громкий шум вреден для слуха.": "Дұрыс. Дыбыс тербелістен пайда болады. Көзден алыстаған сайын дыбыс бәсең. Қатты шу есту қабілетіне зиян.",
"Неверно. Звук возникает от колебаний. Чем дальше источник, тем звук тише. Громкий шум вреден для слуха.": "Бұрыс. Дыбыс тербелістен пайда болады. Көзден алыстаған сайын дыбыс бәсең. Қатты шу есту қабілетіне зиян.",
"Привет! Это Барсик. Сегодня наша тема — «звук и его громкость». Нажимай на карточки и узнавай новое.": "Сәлем! Бұл Барсик. Бүгінгі тақырыбымыз — «дыбыс және оның қаттылығы». Карточкаларды бас та, жаңа нәрсені біл.",
"что такое звук": "дыбыс дегеніміз не",
"Звук возникает, когда тело колеблется: дрожат струна, мембрана, голосовые связки.": "Дене тербелгенде дыбыс пайда болады: ішек, жарғақ, дауыс шымылдығы дірілдейді.",
"как идёт звук": "дыбыс қалай таралады",
"Звук распространяется в воздухе, воде, твёрдых телах. В космосе, где нет воздуха, звука не слышно.": "Дыбыс ауада, суда, қатты денелерде таралады. Ауасыз ғарышта дыбыс естілмейді.",
"громкость": "қаттылық",
"Громкость зависит от силы колебаний и расстояния до источника: чем дальше источник, тем звук тише.": "Қаттылық тербеліс күшіне және көзге дейінгі қашықтыққа байланысты: көз алыс болған сайын дыбыс бәсең.",
"высота": "биіктік",
"Тонкая короткая струна даёт высокий звук, толстая длинная — низкий.": "Жіңішке қысқа ішек биік дыбыс береді, жуан ұзын ішек — төмен дыбыс.",
"Эхо — отражённый звук. Его можно услышать в горах и в большом пустом зале.": "Жаңғырық — шағылысқан дыбыс. Оны тауда және үлкен бос залда естуге болады.",
"шум": "шу",
"Громкая музыка и шум вредят слуху. Громкость измеряют в децибелах. Наушники лучше слушать негромко.": "Қатты музыка мен шу есту қабілетіне зиян. Дыбыс қаттылығын децибелмен өлшейді. Құлаққапты қатты қоспаған жөн.",
