"Для здоровья слуха надо слушать музыку негромко.": "Есту қабілеті үшін музыканы бәсең тыңдау керек.",
"Голос появляется без колебаний связок.": "Дауыс шымылдықтарының тербелісінсіз дауыс шықпайды.",
"Электрическая цепь и экономия энергии": "Электр тізбегі және энергияны үнемдеу",
"Собирать простые схемы цепей и экономить электроэнергию": "Қарапайым тізбектерді құрастыру және электр энергиясын үнемдеу",
"Электрическая цепь состоит из источника, проводов, потребителя и выключателя. Ток идёт только по замкнутой цепи.": "Электр тізбегі көзден, сымдардан, тұтынушыдан және ажыратқыштан тұрады. Ток тек тұйық тізбекпен жүреді.",
"Верно. Электрическая цепь состоит из источника, проводов, потребителя и выключателя. Ток идёт только по замкнутой цепи.": "Дұрыс. Электр тізбегі көзден, сымдардан, тұтынушыдан және ажыратқыштан тұрады. Ток тек тұйық тізбекпен жүреді.",
"Неверно. Электрическая цепь состоит из источника, проводов, потребителя и выключателя. Ток идёт только по замкнутой цепи.": "Бұрыс. Электр тізбегі көзден, сымдардан, тұтынушыдан және ажыратқыштан тұрады. Ток тек тұйық тізбекпен жүреді.",
"Привет! Это Барсик. Сегодня наша тема — «электрическая цепь и экономия энергии». Нажимай на карточки и узнавай новое.": "Сәлем! Бұл Барсик. Бүгінгі тақырыбымыз — «электр тізбегі және энергияны үнемдеу». Карточкаларды бас та, жаңа нәрсені біл.",
"источники тока": "ток көздері",
"Источники электрической энергии — батарейка, аккумулятор, генератор, солнечная батарея. Электростанции вырабатывают ток для городов.": "Электр энергиясының көздері — батарея, аккумулятор, генератор, күн батареясы. Электр станциялары қалаларға ток өндіреді.",
"электростанции": "электр станциялары",
"Есть гидроэлектростанции, тепловые, ветровые и солнечные. В Казахстане работают, например, Бухтарминская и Капшагайская ГЭС.": "Гидроэлектр, жылу, жел және күн станциялары бар. Қазақстанда, мысалы, Бұқтырма және Қапшағай ГЭС-тері жұмыс істейді.",
"В простой цепи есть источник тока, потребитель (лампочка), провода и выключатель. Ток идёт только по замкнутой цепи.": "Қарапайым тізбекте ток көзі, тұтынушы (шам), сымдар және ажыратқыш болады. Ток тек тұйық тізбекпен жүреді.",
"Металлы и вода с солью проводят ток. Резина, пластик, стекло и сухое дерево не проводят — это изоляторы.": "Металдар мен тұзды су токты өткізеді. Резина, пластик, шыны және құрғақ ағаш өткізбейді — бұл оқшаулағыштар.",
"Нельзя трогать оголённые провода, вставлять предметы в розетку, пользоваться приборами мокрыми руками, играть у электропередач.": "Жалаңаш сымдарды ұстауға, розеткаға зат салуға, ылғал қолмен құралдарды пайдалануға, электр желісінің қасында ойнауға болмайды.",
"Выключай свет и приборы, когда не нужны. Используй энергосберегающие лампы. Экономия энергии защищает природу.": "Керек емес кезде жарық пен құралдарды өшір. Энергия үнемдейтін шамдарды пайдалан. Энергияны үнемдеу табиғатты қорғайды.",
"Какая это часть цепи?": "Бұл тізбектің қай бөлігі?",
