"Медь — проводник тока.": "Мыс — токты өткізгіш.",
"Магнит и намагничивание": "Магнит және магниттеу",
"Магнит притягивает железо и сталь. Разноимённые полюса притягиваются, одноимённые отталкиваются.": "Магнит темір мен болатты тартады. Әртүрлі аттас полюстер тартылады, бір аттас полюстер тебіледі.",
"Верно. Магнит притягивает железо и сталь. Разноимённые полюса притягиваются, одноимённые отталкиваются.": "Дұрыс. Магнит темір мен болатты тартады. Әртүрлі аттас полюстер тартылады, бір аттас полюстер тебіледі.",
"Неверно. Магнит притягивает железо и сталь. Разноимённые полюса притягиваются, одноимённые отталкиваются.": "Бұрыс. Магнит темір мен болатты тартады. Әртүрлі аттас полюстер тартылады, бір аттас полюстер тебіледі.",
"Привет! Это Барсик. Сегодня наша тема — «магнит и намагничивание». Нажимай на карточки и узнавай новое.": "Сәлем! Бұл Барсик. Бүгінгі тақырыбымыз — «магнит және магниттеу». Карточкаларды бас та, жаңа нәрсені біл.",
"Магнит притягивает железо, сталь, никель. Дерево, пластик, стекло, медь, алюминий он не притягивает.": "Магнит темірді, болатты, никельді тартады. Ағашты, пластикті, шыныны, мысты, алюминийді тартпайды.",
"сквозь преграду": "кедергі арқылы",
"Магнит действует через бумагу, стекло, воду и даже тонкую доску.": "Магнит қағаз, шыны, су және жұқа тақтай арқылы да әсер етеді.",
"У магнита два полюса: северный и южный. Сильнее всего магнит притягивает у полюсов.": "Магниттің екі полюсі бар: солтүстік және оңтүстік. Магнит полюстерде ең күшті тартады.",
"Разноимённые полюса притягиваются, а одноимённые отталкиваются.": "Әртүрлі аттас полюстер тартылады, ал бір аттас полюстер тебіледі.",
"Железный гвоздь можно намагнитить: потри его несколько раз о магнит в одном направлении.": "Темір шегені магниттеуге болады: оны магнитке бір бағытта бірнеше рет ысқыла.",
"Стрелка компаса — маленький магнит. Она показывает на север и юг, потому что Земля — большой магнит. Удары и нагревание размагничивают магнит.": "Компас тілі — кішкентай магнит. Ол солтүстік пен оңтүстікті көрсетеді, себебі Жер — үлкен магнит. Соққы мен қыздыру магнитті магнитсіздендіреді.",
